export function validateRecoveryStatus(value: unknown, path: string, contract: string, refStack: Set<string>): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "repair_plan")) fail(contract, `${path}.repair_plan`, "missing required property");
  if (!Object.hasOwn(record, "runtime_safety")) fail(contract, `${path}.runtime_safety`, "missing required property");
  if (!Object.hasOwn(record, "invariants")) fail(contract, `${path}.invariants`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "effect_quarantines": {
          if (!Array.isArray(item)) fail(contract, `${path}.effect_quarantines`, "expected array");
          (item as unknown[]).forEach((item, index) => {
            validateUnion(contract, `${`${path}.effect_quarantines`}[${index}]`, [
              () => {
                validateReference("OutcomeUnknownRepositoryEffectQuarantine", validateOutcomeUnknownRepositoryEffectQuarantine, item, `${`${path}.effect_quarantines`}[${index}]`, contract, refStack);
              },
              () => {
                validateReference("PartiallyAppliedRepositoryEffectQuarantine", validatePartiallyAppliedRepositoryEffectQuarantine, item, `${`${path}.effect_quarantines`}[${index}]`, contract, refStack);
              },
              () => {
                validateReference("IndeterminateRepositoryEffectQuarantine", validateIndeterminateRepositoryEffectQuarantine, item, `${`${path}.effect_quarantines`}[${index}]`, contract, refStack);
              },
            ]);
          });
          break;
        }
        case "invariants": {
          validateReference("InvariantAudit", validateInvariantAudit, item, `${path}.invariants`, contract, refStack);
          break;
        }
        case "repair_plan": {
          validateReference("RepairPlan", validateRepairPlan, item, `${path}.repair_plan`, contract, refStack);
          break;
        }
        case "runtime_safety": {
          validateReference("AssessedRuntimeSafetyProof", validateAssessedRuntimeSafetyProof, item, `${path}.runtime_safety`, contract, refStack);
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}

export function validateRejectedUvProject(value: unknown, path: string, contract: string): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "state")) fail(contract, `${path}.state`, "missing required property");
  if (!Object.hasOwn(record, "detail")) fail(contract, `${path}.detail`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "detail": {
          if (typeof item !== "string") fail(contract, `${path}.detail`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.detail`, "must contain at least 1 characters");
          break;
        }
        case "state": {
          if (item !== "project_rejected") fail(contract, `${path}.state`, "did not match required constant");
          if (typeof item !== "string") fail(contract, `${path}.state`, "expected string");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}
